SELECT COUNT(*)
FROM vendor
WHERE email = #{email}

SELECT COUNT(*)
FROM vendor
WHERE email = #{email} AND vendor_id != #{vendorId}

SELECT vendor_id, business_name, business_reg_no, ceo_name, phone, email, password, status, created_at, approved_at
FROM vendor
WHERE email = #{email}

SELECT vendor_id, business_name, business_reg_no, ceo_name, phone, email, password, status, created_at, approved_at
FROM vendor
WHERE vendor_id = #{vendorId}

mapper.update:
UPDATE vendor
SET password = #{password}
WHERE vendor_id = #{vendorId}
